
(function () {
  const MASK_W = 720, MASK_H = 360, ROW_BYTES = MASK_W >> 3;
  const MASK_B64 = "";
  const _bin = atob(MASK_B64), MASK = new Uint8Array(_bin.length);
  for (let i = 0; i < _bin.length; i++) MASK[i] = _bin.charCodeAt(i);
  function isLand(lonDeg, latDeg) {
    let x = Math.floor((lonDeg + 180) / 360 * MASK_W), y = Math.floor((90 - latDeg) / 180 * MASK_H);
    x = ((x % MASK_W) + MASK_W) % MASK_W; if (y < 0) y = 0; else if (y >= MASK_H) y = MASK_H - 1;
    return (MASK[y * ROW_BYTES + (x >> 3)] >> (7 - (x & 7))) & 1;
  }

  const NOTES = ['שינוי באחזקות', 'שינוי בבעלות', 'דירוג אשראי'];

  const THEMES = {
    dark: {
      bg: "radial-gradient(rgba(140,214,232,.05) 1px, transparent 1.5px) 0 0/26px 26px," +
          "radial-gradient(120% 95% at 50% 82%, rgba(0,81,115,.42) 0%, rgba(2,40,58,.28) 42%, rgba(3,5,10,0) 72%)," +
          "linear-gradient(180deg,#061c28 0%,#03050a 100%)",
      ramp: ['#0C6A80', '#5CCDE7', '#9EEDFA'],
      body: 'glow',                      // semi-transparent teal glow over the dark ground
      glow: [[0, [2, 86, 106], 0.55], [1, [0, 43, 61], 0.0]],
      layout: 'horizontal',
    },
    light: {
      bg: "radial-gradient(rgba(120,168,214,.06) 1px, transparent 1.5px) 0 0/26px 26px," +
          "radial-gradient(125% 105% at 50% 12%, #ffffff 0%, #eef3f8 55%, #e2e9f0 100%)",
      ramp: ['#CBD8E2', '#9DBBD4', '#4E9ED4'],   // 1:1 from the baked globe: pale grey-blue → soft blue → bright sky-blue
      body: 'pool',                      // opaque radial steel-grey pool
      layout: 'vertical',
    },
  };

  const CSS = `
    :host{ display:block; position:relative; overflow:hidden; contain:content; }
    :host([theme='dark']){ --plus:#9eedfa; --ring:rgba(92,205,231,.22); --glyph:#032430;
      --card-bg:rgba(1,30,44,.8); --card-border:rgba(255,255,255,.9); --card-text:#fff; }
    :host([theme='light']),:host(:not([theme])){ --plus:#9eedfa; --ring:rgba(92,205,231,.22); --glyph:#0E5A6B;
      --card-bg:rgba(255,255,255,.95); --card-border:rgba(120,168,214,.55); --card-text:#243a4e; }
    .bg{ position:absolute; inset:0; }
    canvas{ position:absolute; inset:0; width:100%; height:100%; display:block; cursor:grab; touch-action:none; }
    canvas:active{ cursor:grabbing; }
    .cards{ position:absolute; inset:0; pointer-events:none; direction:ltr; }
    .dtag{ position:absolute; left:0; top:0; }
    .dbox{ position:absolute; left:0; top:0; transform:scale(var(--cs,1)); transform-origin:0 0; }
    .dplus{ position:absolute; left:-12.5px; top:-12.5px; width:25px; height:25px; border-radius:50%;
      background:var(--plus); box-shadow:0 0 0 3.8px var(--ring);
      opacity:0; transform:scale(.2); transform-origin:center;
      transition:opacity .22s ease, transform .32s cubic-bezier(.2,.9,.25,1.4); }
    .dtag.lit .dplus{ opacity:1; transform:scale(1); }
    .dplus::before,.dplus::after{ content:''; position:absolute; background:var(--glyph); border-radius:1px; }
    .dplus::before{ left:50%; top:6.5px; bottom:6.5px; width:1.7px; transform:translateX(-50%); }
    .dplus::after{ top:50%; left:6.5px; right:6.5px; height:1.7px; transform:translateY(-50%); }
    .dcard{ position:absolute; height:32px; display:flex; align-items:center; padding:0 14px; border-radius:999px;
      background:var(--card-bg); border:1px solid var(--card-border); white-space:nowrap; opacity:0;
      transition:opacity .28s ease, transform .3s cubic-bezier(.2,.9,.25,1.15); }
    .dcard .lbl{ font-size:12.5px; font-weight:400; color:var(--card-text); letter-spacing:-.005em;
      font-family:Heebo,ui-sans-serif,-apple-system,"Helvetica Neue",Arial,sans-serif; }
    .dtag.show .dcard{ opacity:1; }   
    .dline{ position:absolute; }
    
    :host([theme='dark']) .dcard{ top:-16px; transform:scale(.55); backdrop-filter:blur(2px); -webkit-backdrop-filter:blur(2px); }
    :host([theme='dark']) .dtag.show .dcard{ transform:scale(1); }
    :host([theme='dark']) .dtag.r .dcard{ left:18px; transform-origin:left center; }
    :host([theme='dark']) .dtag.l .dcard{ right:18px; transform-origin:right center; }
    
    :host(:not([theme='dark'])) .dcard{ top:-82px; left:0; transform:translateX(-50%) scale(.6);
      transform-origin:center bottom; box-shadow:0 4px 14px rgba(120,150,190,.20); }
    :host(:not([theme='dark'])) .dcard .lbl{ font-weight:500; }
    :host(:not([theme='dark'])) .dtag.show .dcard{ transform:translateX(-50%) scale(1); }
    :host(:not([theme='dark'])) .dline{ left:-.5px; top:-42px; width:1px; height:28px;
      background:linear-gradient(to top, rgba(120,168,214,.75), rgba(120,168,214,.12));
      opacity:0; transform:scaleY(.2); transform-origin:bottom; transition:opacity .25s ease, transform .3s ease; }
    :host(:not([theme='dark'])) .dtag.show .dline{ opacity:1; transform:scaleY(1); }
  `;

  // ---- constants shared with the standalone build ----
  const TILT = 30 * Math.PI / 180, SPEED = 0.17;
  const DOT_LAND = 0.17, LINE_W = 0.09, LINE_OPACITY = 0.15;
  const TARGET_SPACING = 10, GRAD_STEPS = 40, INNER_SCALE = 0.97, R_FIG = 620;
  const hex = v => { v = v.trim().replace('#', ''); return [0, 2, 4].map(i => parseInt(v.slice(i, i + 2), 16)); };
  const mix = (a, b, t) => [0, 1, 2].map(i => a[i] + (b[i] - a[i]) * t);

  class DnbGlobe extends HTMLElement {
    connectedCallback() {
      if (this._init) return; this._init = true;
      const theme = (this.getAttribute('theme') === 'dark') ? 'dark' : (this.getAttribute('theme') === 'light' ? 'light' : 'dark');
      const T = THEMES[theme];
      const root = this.attachShadow({ mode: 'open' });
      const style = document.createElement('style'); style.textContent = CSS; root.appendChild(style);
      const bg = document.createElement('div'); bg.className = 'bg';
      if (this.getAttribute('bg') !== 'off') bg.style.background = T.bg;
      root.appendChild(bg);
      const cv = document.createElement('canvas'); root.appendChild(cv);
      const cardsWrap = document.createElement('div'); cardsWrap.className = 'cards'; root.appendChild(cardsWrap);
      this._run(cv, cardsWrap, theme, T);
    }
    disconnectedCallback() { if (this._raf) cancelAnimationFrame(this._raf); if (this._ro) this._ro.disconnect(); if (this._io) this._io.disconnect(); }

    _run(cv, cardsWrap, theme, T) {
      const ctx = cv.getContext('2d');
      const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
      let W = 0, H = 0, cx = 0, cy = 0, radius = 0, dotPx = 0, linePx = 0, ROWS = 0, COLS = 0;
      const P = { x: [], y: [], z: [], land: [] };
      let SX = null, SY = null, LIM = null, VIS = null;

      function build() {
        const RAD = Math.PI / 180;
        let step = (TARGET_SPACING / radius) * (180 / Math.PI);
        step = Math.max(0.6, Math.min(3, step));
        ROWS = Math.max(2, Math.round(180 / step)); COLS = Math.max(2, Math.round(360 / step));
        const n = ROWS * COLS;
        P.x = new Float32Array(n); P.y = new Float32Array(n); P.z = new Float32Array(n); P.land = new Uint8Array(n);
        for (let r = 0; r < ROWS; r++) {
          const lat = -90 + (r + 0.5) * (180 / ROWS), latR = lat * RAD, ring = Math.cos(latR), y = Math.sin(latR);
          for (let c = 0; c < COLS; c++) {
            const lon = -180 + (c + 0.5) * (360 / COLS), lonR = lon * RAD, i = r * COLS + c;
            P.x[i] = ring * Math.sin(lonR); P.y[i] = y; P.z[i] = ring * Math.cos(lonR);
            P.land[i] = isLand(lon, lat) ? 1 : 0;
          }
        }
        dotPx = TARGET_SPACING; linePx = Math.max(0.6, LINE_W * dotPx);
        SX = new Float32Array(n); SY = new Float32Array(n); LIM = new Float32Array(n); VIS = new Uint8Array(n);
      }
      const resize = () => {
        const d = Math.min(devicePixelRatio || 1, 2), r = cv.getBoundingClientRect();
        W = r.width; H = r.height; if (!W || !H) return;
        cv.width = Math.round(W * d); cv.height = Math.round(H * d); ctx.setTransform(d, 0, 0, d, 0, 0);
        cx = W / 2; cy = H / 2; radius = Math.min(W, H) * 0.42; build();
      };
      this._ro = new ResizeObserver(resize); this._ro.observe(cv); resize();

      let RAMP = [];
      const buildRamp = () => {
        const c1 = hex(T.ramp[0]), c2 = hex(T.ramp[1]), c3 = hex(T.ramp[2]); RAMP = [];
        for (let g = 0; g < GRAD_STEPS; g++) {
          const t = g / (GRAD_STEPS - 1), base = t < 0.5 ? mix(c1, c2, t * 2) : mix(c2, c3, (t - 0.5) * 2);
          RAMP.push('rgb(' + (base[0] | 0) + ',' + (base[1] | 0) + ',' + (base[2] | 0) + ')');
        }
      };
      buildRamp();
      if (document.fonts && document.fonts.ready) document.fonts.ready.then(buildRamp);

      const bucket = Array.from({ length: GRAD_STEPS }, () => []);
      const lineBucket = Array.from({ length: GRAD_STEPS }, () => []);

      let spin = 0, dragging = false, lastX = 0, vel = 0, auto = !reduce;
      cv.addEventListener('pointerdown', e => { dragging = true; auto = false; lastX = e.clientX; vel = 0; cv.setPointerCapture(e.pointerId); });
      cv.addEventListener('pointermove', e => { if (!dragging) return; const d = (e.clientX - lastX) / radius; spin += d; vel = d; lastX = e.clientX; });
      const rel = () => dragging = false; cv.addEventListener('pointerup', rel); cv.addEventListener('pointercancel', rel);

      const sinT = Math.sin(TILT), cosT = Math.cos(TILT);
      let last = performance.now(), vis = true;
      this._io = new IntersectionObserver(e => vis = e[0].isIntersecting, { rootMargin: '160px' }); this._io.observe(cv);

      // ---- cards ----
      const horizontal = T.layout === 'horizontal';
      const SLOT_N = 3; let cardScale = 1;
      const makeCard = () => {
        const el = document.createElement('div'); el.className = 'dtag';
        el.innerHTML = '<div class="dbox">' + (horizontal ? '' : '<span class="dline"></span>') +
          '<span class="dplus"></span><span class="dcard"><span class="lbl"></span></span></div>';
        cardsWrap.appendChild(el);
        return { el, lbl: el.querySelector('.lbl'), idx: -1, t: 0, state: 'idle' };
      };
      const cards = reduce ? [] : Array.from({ length: SLOT_N }, makeCard);
      cards.forEach((s, k) => { s.t = k * 1.8; });
      const depth = i => (LIM[i] - 0.45) / 0.55;
      const busy = i => { const m2 = (radius * 0.34) ** 2; for (const s of cards) { if (s.idx < 0 || s.idx === i) continue; const dx = SX[i] - SX[s.idx], dy = SY[i] - SY[s.idx]; if (dx * dx + dy * dy < m2) return true; } return false; };
      const pickPoint = () => {
        const N = ROWS * COLS, rin2 = (radius * 0.70) ** 2, rout2 = (radius * 0.95) ** 2;
        for (let t = 0; t < 80; t++) {
          const i = (Math.random() * N) | 0;
          if (!VIS[i] || !P.land[i]) continue;
          if (depth(i) < 0.12) continue;
          const dx = SX[i] - cx, dy = SY[i] - cy, d2 = dx * dx + dy * dy;
          if (d2 < rin2 || d2 > rout2) continue;
          if (busy(i)) continue;
          return i;
        }
        return -1;
      };
      const positionCard = s => {
        if (horizontal) { const right = SX[s.idx] >= cx; s.el.classList.toggle('r', right); s.el.classList.toggle('l', !right); }
        s.el.style.transform = 'translate(' + SX[s.idx] + 'px,' + SY[s.idx] + 'px)';
      };
      const openCount = () => { let n = 0; for (const s of cards) if (s.state === 'open') n++; return n; };
      const tickCards = dt => {
        const cs = radius / R_FIG;
        if (cs !== cardScale) { cardScale = cs; for (const s of cards) s.el.style.setProperty('--cs', cs.toFixed(3)); }
        for (const s of cards) {
          s.t -= dt;
          if (s.state === 'idle') {
            if (s.t <= 0) { const i = pickPoint();
              if (i < 0) { s.t = 0.1; }
              else { s.idx = i; s.state = 'light'; s.t = 0.32; s.lbl.textContent = NOTES[(Math.random() * NOTES.length) | 0]; positionCard(s); s.el.classList.add('lit'); } }
          } else if (s.state === 'light') {
            if (s.t <= 0) { s.el.classList.add('show'); s.state = 'open'; s.t = 3.6 + Math.random() * 2.2; }
          } else if (s.state === 'open') {
            if (!VIS[s.idx]) { s.el.classList.remove('show'); s.state = 'close'; s.t = 0.34; }
            else if (s.t <= 0) { if (openCount() > 2) { s.el.classList.remove('show'); s.state = 'close'; s.t = 0.34; } else s.t = 0.5 + Math.random() * 0.7; }
          } else if (s.state === 'close') {
            if (s.t <= 0) { s.el.classList.remove('lit'); s.idx = -1; s.state = 'idle'; s.t = 0.3 + Math.random() * 0.6; }
          }
          if (s.idx >= 0 && VIS[s.idx]) positionCard(s);
        }
      };

      const drawBody = () => {
        const innerR = radius * INNER_SCALE;
        if (T.body === 'pool') {
          const gy = cy + radius * 0.16;
          const g = ctx.createRadialGradient(cx, gy, radius * 0.04, cx, gy, radius * 1.02);
          g.addColorStop(0.00, '#ADC4CD'); g.addColorStop(0.42, '#C6D5DD'); g.addColorStop(0.72, '#E3ECF1'); g.addColorStop(1.00, '#F3F7FB');
          ctx.beginPath(); ctx.arc(cx, cy, innerR, 0, 6.283185); ctx.fillStyle = g; ctx.fill();
        } else {
          const g = ctx.createRadialGradient(cx, cy, innerR * 0.05, cx, cy, innerR);
          for (const [pos, col, a] of T.glow) g.addColorStop(pos, 'rgba(' + col[0] + ',' + col[1] + ',' + col[2] + ',' + a + ')');
          ctx.beginPath(); ctx.arc(cx, cy, innerR, 0, 6.283185); ctx.fillStyle = g; ctx.fill();
        }
      };

      const frame = now => {
        this._raf = requestAnimationFrame(frame);
        if (!vis || !radius) { last = now; return; }
        const dt = Math.min((now - last) / 1000, .05); last = now;
        if (!dragging) { if (auto) spin += SPEED * dt; else { spin += vel; vel *= .94; if (Math.abs(vel) < .0004) { vel = 0; auto = !reduce; } } }
        ctx.clearRect(0, 0, W, H);
        drawBody();
        const sinS = Math.sin(spin), cosS = Math.cos(spin);
        for (let i = 0; i < GRAD_STEPS; i++) { bucket[i].length = 0; lineBucket[i].length = 0; }
        const N = ROWS * COLS;
        for (let i = 0; i < N; i++) {
          const px = P.x[i], py = P.y[i], pz = P.z[i];
          const x1 = px * cosS + pz * sinS, z1 = -px * sinS + pz * cosS, y2 = py * cosT - z1 * sinT, z2 = py * sinT + z1 * cosT;
          if (z2 <= 0) { VIS[i] = 0; continue; }
          VIS[i] = 1; SX[i] = cx + x1 * radius; SY[i] = cy - y2 * radius; LIM[i] = 0.45 + 0.55 * z2;
        }
        tickCards(dt);
        for (let i = 0; i < N; i++) {
          if (!VIS[i] || !P.land[i]) continue;
          const R = DOT_LAND * dotPx * LIM[i]; if (R < 0.35) continue;
          let g = ((SX[i] - (cx - radius)) / (2 * radius)) * 0.78 + (1 - (SY[i] - (cy - radius)) / (2 * radius)) * 0.22;
          g = g < 0 ? 0 : g > 0.999 ? 0.999 : g; bucket[(g * GRAD_STEPS) | 0].push(SX[i], SY[i], R);
        }
        for (let r = 0; r < ROWS; r++) { const base = r * COLS;
          for (let c = 0; c < COLS; c++) { const i = base + c, j = base + ((c + 1) % COLS);
            if (!VIS[i] || !VIS[j] || P.land[i] || P.land[j]) continue;
            const mx = (SX[i] + SX[j]) / 2, my = (SY[i] + SY[j]) / 2;
            let g = ((mx - (cx - radius)) / (2 * radius)) * 0.78 + (1 - (my - (cy - radius)) / (2 * radius)) * 0.22;
            g = g < 0 ? 0 : g > 0.999 ? 0.999 : g; lineBucket[(g * GRAD_STEPS) | 0].push(SX[i], SY[i], SX[j], SY[j]); } }
        for (let gi = 0; gi < GRAD_STEPS; gi++) { const b = bucket[gi]; if (!b.length) continue;
          ctx.fillStyle = RAMP[gi]; ctx.beginPath();
          for (let k = 0; k < b.length; k += 3) { ctx.moveTo(b[k] + b[k + 2], b[k + 1]); ctx.arc(b[k], b[k + 1], b[k + 2], 0, 6.283185); } ctx.fill(); }
        ctx.lineWidth = linePx; ctx.globalAlpha = LINE_OPACITY;
        for (let gi = 0; gi < GRAD_STEPS; gi++) { const b = lineBucket[gi]; if (!b.length) continue;
          ctx.strokeStyle = RAMP[gi]; ctx.beginPath();
          for (let k = 0; k < b.length; k += 4) { ctx.moveTo(b[k], b[k + 1]); ctx.lineTo(b[k + 2], b[k + 3]); } ctx.stroke(); }
        ctx.globalAlpha = 1;
      };
      this._raf = requestAnimationFrame(frame);
    }
  }
  if (!customElements.get('dnb-globe')) customElements.define('dnb-globe', DnbGlobe);
})();
